#include <iostream>
#include <vector>
struct Model { int value = 0, rejected = 0; };
void dispatch(Model& m, int event) {
  if (event == 0) m.value = 0;
  else if (event == 1 && m.value < 10) ++m.value;
  else if (event == -1 && m.value > 0) --m.value;
  else ++m.rejected;
}
int main() {
  int n;
  if (!(std::cin >> n) || n < 0 || n > 20) { std::cout << "invalid\n"; return 0; }
  std::vector<int> events(n);
  for (int& e : events) if (!(std::cin >> e)) { std::cout << "invalid\n"; return 0; }
  std::cin >> std::ws;
  if (!std::cin.eof()) { std::cout << "invalid\n"; return 0; }
  Model model;
  for (int e : events) dispatch(model, e);
  std::cout << "value " << model.value << " rejected " << model.rejected << '\n';
}

